        .about("Ping, but with a graph.")
        .version("1.20.1")
        .long_version("gping 1.20.1\ncommit_hash: 42449c03\nbuild_time: 2026-06-11 22:08:42 +00:00\nbuild_env: rustc 1.92.0 (ded5c06cf 2025-12-08),1.92.0-x86_64-unknown-linux-gnu")
        .arg(
            Arg::new("cmd")
                .long("cmd")
                .action(ArgAction::SetTrue)
                .help("Graph the execution time for a list of commands rather than pinging hosts"),
        )
        .arg(
            Arg::new("watch_interval")
                .short('n')
                .long("watch-interval")
                .value_name("WATCH_INTERVAL")
                .value_parser(clap::value_parser!(f64))
                .help("Watch interval seconds (provide partial seconds like '0.5'). Default for ping is 0.2, default for cmd is 0.5"),
        )
        .arg(
            Arg::new("buffer")
                .short('b')
                .long("buffer")
                .value_name("BUFFER")
                .default_value("30")
                .value_parser(clap::value_parser!(usize))
                .help("Determines the number of seconds to display in the graph"),
        )
        .arg(
            Arg::new("ipv4")
                .short('4')
                .action(ArgAction::SetTrue)
                .conflicts_with("ipv6")
                .help("Resolve ping targets to IPv4 address"),
        )
        .arg(
            Arg::new("ipv6")
                .short('6')
                .action(ArgAction::SetTrue)
                .conflicts_with("ipv4")
                .help("Resolve ping targets to IPv6 address"),
        )
        .arg(
            Arg::new("interface")
                .short('i')
                .long("interface")
                .value_name("INTERFACE")
                .help("Interface to use when pinging"),
        )
        .arg(
            Arg::new("simple_graphics")
                .short('s')
                .long("simple-graphics")
                .action(ArgAction::SetTrue)
                .help(""),
        )
        .arg(
            Arg::new("vertical_margin")
                .long("vertical-margin")
                .value_name("VERTICAL_MARGIN")
                .default_value("1")
                .value_parser(clap::value_parser!(u16))
                .help("Vertical margin around the graph (top and bottom)"),
        )
        .arg(
            Arg::new("horizontal_margin")
                .long("horizontal-margin")
                .value_name("HORIZONTAL_MARGIN")
                .default_value("0")
                .value_parser(clap::value_parser!(u16))
                .help("Horizontal margin around the graph (left and right)"),
        )
        .arg(
            Arg::new("color")
                .short('c')
                .long("color")
                .value_name("color")
                .action(ArgAction::Append)
