use anyhow::{Context, Result};
use chrono::Local;
use clap::{Arg, ArgAction, Command};
use crossterm::{
    event::{self, Event, KeyCode, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Constraint, Direction, Layout},
    style::{Color, Style},
    symbols::Marker,
    widgets::{Axis, Chart, Dataset, GraphType, Paragraph},
    Terminal,
};
use std::{
    collections::VecDeque,
    io::{self, BufRead, BufReader},
    net::ToSocketAddrs,
    process::{Command as ProcessCommand, Stdio},
    sync::{
        atomic::{AtomicBool, Ordering},
        mpsc, Arc,
    },
    thread,
    time::{Duration, Instant},
};

#[derive(Debug, Clone)]
enum PingResult {
    Pong(Duration),
    Timeout,
}

struct Sample {
    time: Instant,
    result: PingResult,
}

struct TargetBuffer {
    label: String,
    color: Color,
    samples: VecDeque<Sample>,
    timeout_count: usize,
}

impl TargetBuffer {
    fn new(label: String, color: Color) -> Self {
        Self {
            label,
            color,
            samples: VecDeque::new(),
            timeout_count: 0,
        }
    }

    fn add_sample(&mut self, result: PingResult) {
        if matches!(result, PingResult::Timeout) {
            self.timeout_count += 1;
        }
        self.samples.push_back(Sample {
            time: Instant::now(),
            result,
        });
    }

    fn prune(&mut self, buffer_secs: u64) {
        let cutoff = Instant::now().checked_sub(Duration::from_secs(buffer_secs)).unwrap_or_else(Instant::now);
        while let Some(sample) = self.samples.front() {
            if sample.time < cutoff {
                self.samples.pop_front();
            } else {
                break;
            }
        }
    }

    fn clear(&mut self) {
        self.samples.clear();
        self.timeout_count = 0;
    }

    fn stats(&self) -> (Option<Duration>, Option<Duration>, Option<Duration>, Option<Duration>, Duration, Duration) {
        let pongs: Vec<Duration> = self
            .samples
            .iter()
            .filter_map(|s| match s.result {
                PingResult::Pong(d) => Some(d),
                _ => None,
            })
            .collect();

        if pongs.is_empty() {
            return (None, None, None, None, Duration::ZERO, Duration::ZERO);
        }

        let last = pongs.last().copied();
        let min = pongs.iter().min().copied();
        let max = pongs.iter().max().copied();
        let sum: Duration = pongs.iter().sum();
        let avg = Some(sum / pongs.len() as u32);

        let jitter = if pongs.len() >= 2 {
            let mut diff_sum = Duration::ZERO;
            for i in 1..pongs.len() {
                let diff = if pongs[i] >= pongs[i - 1] {
                    pongs[i] - pongs[i - 1]
                } else {
                    pongs[i - 1] - pongs[i]
                };
                diff_sum += diff;
            }
            diff_sum / (pongs.len() - 1) as u32
        } else {
            Duration::ZERO
        };

        let mut sorted = pongs.clone();
        sorted.sort();
        let idx = ((sorted.len() as f64) * 0.95) as usize;
        let idx = idx.min(sorted.len() - 1);
        let p95 = sorted[idx];

        (last, min, max, avg, jitter, p95)
    }
}

const DEFAULT_PALETTE: &[Color] = &[
    Color::Green,
    Color::Yellow,
    Color::Blue,
    Color::Magenta,
    Color::Cyan,
    Color::White,
    Color::DarkGray,
    Color::LightRed,
    Color::LightGreen,
    Color::LightYellow,
    Color::LightBlue,
    Color::LightMagenta,
    Color::LightCyan,
];

fn parse_color(s: &str) -> Result<Color> {
    let s_lower = s.to_lowercase();
    match s_lower.as_str() {
        "black" => Ok(Color::Black),
        "red" => Ok(Color::Red),
        "green" => Ok(Color::Green),
        "yellow" => Ok(Color::Yellow),
        "blue" => Ok(Color::Blue),
        "magenta" => Ok(Color::Magenta),
        "cyan" => Ok(Color::Cyan),
        "gray" => Ok(Color::Gray),
        "dark-gray" => Ok(Color::DarkGray),
        "light-red" => Ok(Color::LightRed),
        "light-green" => Ok(Color::LightGreen),
        "light-yellow" => Ok(Color::LightYellow),
        "light-blue" => Ok(Color::LightBlue),
        "light-magenta" => Ok(Color::LightMagenta),
        "light-cyan" => Ok(Color::LightCyan),
        "white" => Ok(Color::White),
        hex if hex.starts_with('#') && hex.len() == 7 => {
            let r = u8::from_str_radix(&hex[1..3], 16).map_err(|_| anyhow::anyhow!("Failed to parse Colors"))?;
            let g = u8::from_str_radix(&hex[3..5], 16).map_err(|_| anyhow::anyhow!("Failed to parse Colors"))?;
            let b = u8::from_str_radix(&hex[5..7], 16).map_err(|_| anyhow::anyhow!("Failed to parse Colors"))?;
            Ok(Color::Rgb(r, g, b))
        }
        _ => Err(anyhow::anyhow!("Failed to parse Colors")).context(format!("Invalid color code: `{s}`")),
    }
}

fn format_duration(d: Duration) -> String {
    let nanos = d.as_nanos();
    if nanos == 0 {
        return "0ns".to_string();
    }
    if nanos < 1_000 {
        return format!("{nanos}ns");
    }
    if nanos < 1_000_000 {
        let micros = d.as_micros();
        return format!("{micros}µs");
    }
    if nanos < 1_000_000_000 {
        let ms = nanos as f64 / 1_000_000.0;
        let s = format!("{:.3}", ms);
        let trimmed = s.trim_end_matches('0').trim_end_matches('.');
        return format!("{trimmed}ms");
    }
    let secs = nanos as f64 / 1_000_000_000.0;
    let s = format!("{:.6}", secs);
    let trimmed = s.trim_end_matches('0').trim_end_matches('.');
    format!("{trimmed}s")
}

fn resolve_target(target: &str) -> Result<String> {
    let host = if target.starts_with("aws:") {
        let region = &target[4..];
        format!("ec2.{region}.amazonaws.com")
    } else {
        target.to_string()
    };

    let addr_str = format!("{host}:80");
    match addr_str.to_socket_addrs() {
        Ok(_) => Ok(host),
        Err(e) => Err(anyhow::Error::from(e)).context(format!("Resolving {host}")),
    }
}

fn build_cli() -> Command {
