        .about("Ping, but with a graph.")
        .version("1.20.1")
        .long_version("gping 1.20.1\ncommit_hash: 42449c03\nbuild_time: 2026-06-11 22:08:42 +00:00\nbuild_env: rustc 1.92.0 (ded5c06cf 2025-12-08),1.92.0-x86_64-unknown-linux-gnu")
        .arg(
            Arg::new("cmd")
                .long("cmd")
                .action(ArgAction::SetTrue)
                .help("Graph the execution time for a list of commands rather than pinging hosts"),
