        )
        .arg(
            Arg::new("clear")
                .long("clear")
                .action(ArgAction::SetTrue)
                .help("Clear the graph from the terminal after closing the program"),
        )
        .arg(
            Arg::new("ping_args")
                .long("ping-args")
                .value_name("PING_ARGS")
                .num_args(0..)
                .help("Extra arguments to pass to `ping`. These are platform dependent"),
        )
        .arg(
            Arg::new("hosts_or_commands")
                .value_name("HOSTS_OR_COMMANDS")
