fn run_cmd_worker(
    target_idx: usize,
    cmd_str: String,
    interval: Duration,
    tx: mpsc::Sender<(usize, PingResult)>,
    running: Arc<AtomicBool>,
) {
    while running.load(Ordering::Relaxed) {
        let start = Instant::now();
        let child = ProcessCommand::new("sh")
            .arg("-c")
            .arg(&cmd_str)
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status();

        let elapsed = start.elapsed();
        let res = match child {
            Ok(status) if status.success() => PingResult::Pong(elapsed),
            _ => PingResult::Timeout,
        };

        if tx.send((target_idx, res)).is_err() {
            break;
        }

        let rem = interval.saturating_sub(elapsed);
        thread::sleep(rem);
    }
}

fn parse_ping_time(line: &str) -> Option<f64> {
    if let Some(idx) = line.find("time=") {
        let rest = &line[idx + 5..];
        let num_str: String = rest.chars().take_while(|c| c.is_ascii_digit() || *c == '.').collect();
        if let Ok(ms) = num_str.parse::<f64>() {
            return Some(ms);
        }
    }
    None
}

fn main() {
    if let Err(e) = run() {
        eprintln!("Error: {e:?}");
        std::process::exit(1);
    }
}

fn run() -> Result<()> {
    let matches = build_cli().get_matches();

    let raw_targets: Vec<String> = matches
        .get_many::<String>("hosts_or_commands")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    if raw_targets.is_empty() {
        eprintln!("Error: At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments.");
        std::process::exit(1);
    }

    let is_cmd = matches.get_flag("cmd");

    let mut user_colors = Vec::new();
    if let Some(cols) = matches.get_many::<String>("color") {
        for c_str in cols {
            let col = parse_color(c_str)?;
            user_colors.push(col);
        }
    }

    let mut targets = Vec::new();
    if is_cmd {
        targets = raw_targets;
    } else {
        for t in raw_targets {
            let resolved = resolve_target(&t)?;
            targets.push(resolved);
        }
    }

    let watch_interval_sec = matches
        .get_one::<f64>("watch_interval")
        .copied()
        .unwrap_or(if is_cmd { 0.5 } else { 0.2 });

    let watch_interval = Duration::from_secs_f64(watch_interval_sec);
    let buffer_secs = *matches.get_one::<usize>("buffer").unwrap() as u64;
    let simple_graphics = matches.get_flag("simple_graphics");
    let vertical_margin = *matches.get_one::<u16>("vertical_margin").unwrap();
    let horizontal_margin = *matches.get_one::<u16>("horizontal_margin").unwrap();
    let clear_on_exit = matches.get_flag("clear");

    let use_ipv4 = matches.get_flag("ipv4");
    let use_ipv6 = matches.get_flag("ipv6");
    let interface = matches.get_one::<String>("interface").cloned();
    let ping_args: Vec<String> = matches
        .get_many::<String>("ping_args")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    let mut buffers = Vec::new();
    for (i, target) in targets.iter().enumerate() {
        let color = if i < user_colors.len() {
            user_colors[i]
        } else {
            DEFAULT_PALETTE[i % DEFAULT_PALETTE.len()]
        };
        buffers.push(TargetBuffer::new(target.clone(), color));
    }

    let (tx, rx) = mpsc::channel();
    let running = Arc::new(AtomicBool::new(true));

    if is_cmd {
        for (idx, target) in targets.iter().enumerate() {
            let tx_c = tx.clone();
            let r_c = Arc::clone(&running);
            let cmd_str = target.clone();
            thread::spawn(move || {
                run_cmd_worker(idx, cmd_str, watch_interval, tx_c, r_c);
            });
        }
    } else {
        for (idx, target) in targets.iter().enumerate() {
            let mut args = Vec::new();
            if use_ipv4 {
                args.push("-4".to_string());
            }
            if use_ipv6 {
                args.push("-6".to_string());
            }
            if let Some(ref iface) = interface {
                args.push("-I".to_string());
                args.push(iface.clone());
            }
            args.push("-i".to_string());
            args.push(format!("{watch_interval_sec}"));
            args.extend(ping_args.clone());
            args.push(target.clone());

            let mut child = ProcessCommand::new("ping")
                .args(&args)
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .context("Error spawning ping")?;

            let stdout = child.stdout.take().unwrap();
            let reader = BufReader::new(stdout);
            let tx_c = tx.clone();
            let r_c = Arc::clone(&running);

            thread::spawn(move || {
                for line_res in reader.lines() {
                    if !r_c.load(Ordering::Relaxed) {
                        break;
                    }
                    if let Ok(line) = line_res {
                        if let Some(ms) = parse_ping_time(&line) {
                            let d = Duration::from_secs_f64(ms / 1000.0);
                            let _ = tx_c.send((idx, PingResult::Pong(d)));
                        } else if line.contains("timeout") || line.contains("Unreachable") {
                            let _ = tx_c.send((idx, PingResult::Timeout));
                        }
                    }
                }
            });
        }
    }

    let is_paused = Arc::new(AtomicBool::new(false));

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    if clear_on_exit {
        execute!(stdout, EnterAlternateScreen)?;
    }
    execute!(stdout, crossterm::cursor::Hide)?;

    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let buffer_start = Instant::now();

    loop {
        while let Ok((idx, res)) = rx.try_recv() {
            if !is_paused.load(Ordering::Relaxed) {
                buffers[idx].add_sample(res);
            }
        }

        for b in &mut buffers {
            b.prune(buffer_secs);
        }

        terminal.draw(|f| {
            render_ui(f, &buffers, buffer_secs, buffer_start, simple_graphics, vertical_margin, horizontal_margin);
        })?;

        if event::poll(Duration::from_millis(50))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char('q') | KeyCode::Esc => break,
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => break,
                    KeyCode::Char('c') => {
                        for b in &mut buffers {
                            b.clear();
                        }
                    }
                    KeyCode::Char(' ') | KeyCode::Char('p') => {
                        let paused = is_paused.load(Ordering::Relaxed);
                        is_paused.store(!paused, Ordering::Relaxed);
                    }
                    _ => {}
                }
            }
        }
    }

    running.store(false, Ordering::Relaxed);
    disable_raw_mode()?;
    if clear_on_exit {
        execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    }
    execute!(terminal.backend_mut(), crossterm::cursor::Show)?;

    Ok(())
}

fn render_ui(
    f: &mut ratatui::Frame,
    buffers: &[TargetBuffer],
    buffer_secs: u64,
    _buffer_start: Instant,
    simple_graphics: bool,
    vertical_margin: u16,
    horizontal_margin: u16,
) {
    let size = f.area();

    let vertical_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(vertical_margin),
            Constraint::Min(0),
            Constraint::Length(vertical_margin),
        ])
        .split(size);

    let inner_area = vertical_chunks[1];

    let horizontal_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Length(horizontal_margin),
            Constraint::Min(0),
            Constraint::Length(horizontal_margin),
        ])
        .split(inner_area);

    let content_area = horizontal_chunks[1];

    if content_area.width == 0 || content_area.height == 0 {
        return;
    }

    let num_targets = buffers.len() as u16;
    let main_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(num_targets),
            Constraint::Min(0),
        ])
        .split(content_area);

    let header_area = main_chunks[0];
    let chart_area = main_chunks[1];

    let header_rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints(vec![Constraint::Length(1); buffers.len()])
        .split(header_area);

    for (i, buf) in buffers.iter().enumerate() {
        if i >= header_rows.len() {
            break;
        }
        let row_area = header_rows[i];
        let cols = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([
                Constraint::Percentage(30),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
            ])
            .split(row_area);

        let (last, min, max, avg, jitter, p95) = buf.stats();
        let style = Style::default().fg(buf.color);

        f.render_widget(Paragraph::new(buf.label.clone()).style(style), cols[0]);

        if let (Some(last), Some(min), Some(max), Some(avg)) = (last, min, max, avg) {
            f.render_widget(Paragraph::new(format!("last {}", format_duration(last))).style(style), cols[1]);
            f.render_widget(Paragraph::new(format!("min {}", format_duration(min))).style(style), cols[2]);
            f.render_widget(Paragraph::new(format!("max {}", format_duration(max))).style(style), cols[3]);
            f.render_widget(Paragraph::new(format!("avg {}", format_duration(avg))).style(style), cols[4]);
            f.render_widget(Paragraph::new(format!("jtr {}", format_duration(jitter))).style(style), cols[5]);
            f.render_widget(Paragraph::new(format!("p95 {}", format_duration(p95))).style(style), cols[6]);
            f.render_widget(Paragraph::new(format!("t/o {}", buf.timeout_count)).style(style), cols[7]);
        } else if buf.timeout_count > 0 {
            f.render_widget(Paragraph::new(format!("t/o {}", buf.timeout_count)).style(style), cols[7]);
        }
    }

    let mut all_pongs = Vec::new();
    for buf in buffers {
        for s in &buf.samples {
            if let PingResult::Pong(d) = s.result {
                all_pongs.push(d.as_nanos() as f64);
            }
        }
    }

    let (y_min, y_max) = if all_pongs.is_empty() {
        (0.0, 1.0)
    } else {
        let mut min_val = f64::MAX;
        let mut max_val = f64::MIN;
        for v in all_pongs {
            if v < min_val {
                min_val = v;
            }
            if v > max_val {
                max_val = v;
            }
        }
        if (max_val - min_val).abs() < 1e-6 {
            min_val *= 0.9;
            max_val *= 1.1;
            if max_val == 0.0 {
                max_val = 1.0;
            }
        }
        (min_val, max_val)
    };

    let now = Instant::now();
    let buffer_duration = Duration::from_secs(buffer_secs);
    let start_time = now.checked_sub(buffer_duration).unwrap_or(now);

    let mut raw_data: Vec<Vec<(f64, f64)>> = Vec::new();

    for buf in buffers {
        let mut target_points = Vec::new();
        for s in &buf.samples {
            let x = if s.time >= start_time {
                s.time.duration_since(start_time).as_secs_f64()
            } else {
                0.0
            };
            let y = match s.result {
                PingResult::Pong(d) => d.as_nanos() as f64,
                PingResult::Timeout => y_max,
            };
            target_points.push((x, y));
        }
        raw_data.push(target_points);
    }

    let marker = if simple_graphics {
        Marker::Dot
    } else {
        Marker::Braille
    };

    let datasets: Vec<Dataset> = buffers
        .iter()
        .zip(raw_data.iter())
        .map(|(buf, data)| {
            Dataset::default()
                .marker(marker)
                .graph_type(GraphType::Line)
                .style(Style::default().fg(buf.color))
                .data(data)
        })
        .collect();

    let y_step = (y_max - y_min) / 6.0;
    let y_labels: Vec<String> = (0..=6)
        .map(|i| {
            let val = y_min + i as f64 * y_step;
            format_duration(Duration::from_nanos(val as u64))
        })
        .collect();

    let now_local = Local::now();
    let half_buffer = Duration::from_secs(buffer_secs / 2);
    let full_buffer = Duration::from_secs(buffer_secs);

    let end_time_str = now_local.format("%H:%M:%S").to_string();
    let mid_time_str = (now_local - chrono::Duration::from_std(half_buffer).unwrap_or_default())
        .format("%H:%M:%S")
        .to_string();
    let start_time_str = (now_local - chrono::Duration::from_std(full_buffer).unwrap_or_default())
        .format("%H:%M:%S")
        .to_string();

    let chart = Chart::new(datasets)
        .x_axis(
            Axis::default()
                .bounds([0.0, buffer_secs as f64])
                .labels(vec![start_time_str, mid_time_str, end_time_str]),
        )
        .y_axis(
            Axis::default()
                .bounds([y_min, y_max])
                .labels(y_labels),
        );

    f.render_widget(chart, chart_area);
}
